CREATE OR REPLACE FUNCTION public.add_post_comment(p_post_id uuid, p_body text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_owner uuid;
  v_can_view boolean;
begin
  if not public.enforcement_gate('rpc.add_post_comment') then
    raise exception 'not permitted';
  end if;
  if p_body is null or btrim(p_body) = '' then
    return;
  end if;

  select owner_user_id into v_owner
  from public.posts
  where id = p_post_id;

  if v_owner is null then
    raise exception 'post not found';
  end if;

  -- canonical can-view-post: owner OR approved follower of owner
  select (
    (v_owner = auth.uid())
    or exists (
      select 1
      from public.follows f
      where (f.follower_user_id = auth.uid())
        and (f.followed_user_id = v_owner)
        and (f.status = 'approved'::text)
    )
  ) into v_can_view;

  if not v_can_view then
    raise exception 'not permitted';
  end if;

  -- non-owner only
  if auth.uid() = v_owner then
    raise exception 'owner must reply via reply_to_commenter/respond_to_commenters';
  end if;

  insert into public.post_comments (post_id, owner_user_id, author_user_id, recipient_user_id, body)
  values (p_post_id, v_owner, auth.uid(), v_owner, p_body);
end;
$function$

CREATE OR REPLACE FUNCTION public.enforcement_gate(p_surface text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_enforcing boolean;
  v_allow     boolean;
  v_uid       uuid;
  v_clause    text;
begin
  v_enforcing := public.enforcement_active();
  if v_enforcing then
    v_allow := coalesce(public.connected_member_self(), false);
  else
    v_allow := true;
  end if;

  begin
    v_uid := (select auth.uid());
    if v_uid is not null then
      v_clause := public.membership_state(v_uid);
      insert into public.shadow_enforcement_stat as s
        (user_id, surface, decided_clause, bucket_hour, would_deny, enforced)
      values (v_uid, p_surface, v_clause, date_trunc('hour', now()), not v_allow, v_enforcing)
      on conflict (user_id, surface, decided_clause, bucket_hour, enforced) do update
        set observations = s.observations + 1,
            last_seen    = now(),
            would_deny   = excluded.would_deny;
    end if;
  exception when others then
    null;                      -- telemetry that can fail a request is not telemetry
  end;

  return v_allow;
end
$function$

CREATE OR REPLACE FUNCTION public.membership_establish_v1(p_user_id uuid, p_environment text, p_original_transaction_id text, p_apple_token uuid, p_jws_token uuid, p_state jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_binding   uuid;
  v_owner     uuid;
  v_method    text;
  v_signed    timestamptz := (p_state->>'renewal_info_signed_date')::timestamptz;
  v_product   text        := nullif(p_state->>'product_id', '');
  v_renewal   timestamptz := nullif(p_state->>'renewal_date', '')::timestamptz;
  v_grace     timestamptz := nullif(p_state->>'grace_period_expires_date', '')::timestamptz;
  v_retry     boolean     := coalesce((p_state->>'is_in_billing_retry')::boolean, false);
  v_entitled  boolean;
  v_existing  text;
begin
  -- HARD PRECONDITIONS. Every one is unreachable from a correct caller; if one
  -- fires the defect is upstream, and stopping is better than writing.
  if p_user_id is null then
    raise exception 'membership_establish_v1: no user_id' using errcode = '22004';
  end if;
  if p_environment is null or p_environment not in ('Sandbox', 'Production') then
    raise exception 'membership_establish_v1: bad environment' using errcode = '22023';
  end if;
  if p_original_transaction_id is null then
    raise exception 'membership_establish_v1: no original_transaction_id' using errcode = '22004';
  end if;
  if v_signed is null then
    raise exception 'membership_establish_v1: no renewal_info_signed_date' using errcode = '22004';
  end if;
  if v_product is null then
    raise exception 'membership_establish_v1: no product_id' using errcode = '22004';
  end if;

  -- The caller must already hold a binding token. ensure_membership_binding()
  -- is idempotent and client-reachable, so this is the caller's own doing.
  select b.binding_token into v_binding
    from public.membership_binding b
   where b.user_id = p_user_id;
  if v_binding is null then
    raise exception 'membership_establish_v1: no binding for %', p_user_id
      using errcode = '23514';
  end if;

  -- ---------------------------------------------------------------- decide
  --
  -- RESOLUTION HAPPENS INSIDE THIS TRANSACTION, against the live binding table,
  -- and not in the caller. A decision taken before the network round trip and
  -- trusted afterwards is a TOCTOU race: a concurrent binding change between the
  -- Apple read and the write would otherwise be invisible.
  if p_apple_token is null then
    -- Apple reports no token. Binding it is a LEGACY CLAIM, which requires
    -- Set App Account Token plus an independent Apple re-read -- an HTTPS round
    -- trip that must never happen inside a transaction. U5c/U5d own it.
    return jsonb_build_object(
      'outcome', 'requires_claim',
      'reason', 'apple reports no appAccountToken; legacy claim belongs to U5c/U5d',
      'established', false);
  end if;

  v_owner := public.membership_resolve_binding_v1(p_apple_token);

  if v_owner is null then
    -- An ORPHAN token -- typically left by an explicit account deletion. A
    -- JWS-verified claimant may rebind, but rebinding also means calling
    -- Set App Account Token and re-reading. Same boundary as above.
    return jsonb_build_object(
      'outcome', 'requires_claim',
      'reason', 'apple token matches no live binding (orphan); rebind belongs to U5c/U5d',
      'established', false);
  end if;

  if v_owner <> p_user_id then
    -- A LIVE BINDING BELONGING TO SOMEBODY ELSE. Grant nothing, change nothing,
    -- and never call Set App Account Token -- Apple would let us overwrite it,
    -- which is precisely why our rule has to be the protection (B-24).
    insert into public.membership_binding_conflict as c (
        user_id, environment, original_transaction_id, conflict_kind)
    values (p_user_id, p_environment, p_original_transaction_id,
            'live_binding_mismatch')
    on conflict (user_id, environment, original_transaction_id) do update
       set observed_count = c.observed_count + 1,
           last_seen_at   = now();

    return jsonb_build_object(
      'outcome', 'conflict',
      'reason', 'appAccountToken belongs to another live binding',
      'established', false);
  end if;

  -- Apple reports OUR token. Provenance is decided by which artefact carried it.
  v_method := case when p_jws_token is not distinct from v_binding
                   then 'purchase' else 'legacy_claim' end;

  v_entitled := coalesce(v_renewal > now(), false)
             or coalesce(v_retry and v_grace > now(), false);

  -- ---------------------------------------------------------------- write
  begin
    insert into public.membership (
        user_id, environment, original_transaction_id, product_id,
        apple_status, renewal_date, grace_period_expires_date,
        is_in_billing_retry, auto_renew_status, expiration_intent,
        revocation_date, renewal_info_signed_date,
        binding_method, bound_at,
        entitlement_ended_at, pending_cleanup_at)
    values (
        p_user_id, p_environment, p_original_transaction_id, v_product,
        (p_state->>'apple_status')::smallint, v_renewal, v_grace,
        v_retry, (p_state->>'auto_renew_status')::smallint,
        (p_state->>'expiration_intent')::smallint,
        nullif(p_state->>'revocation_date', '')::timestamptz, v_signed,
        v_method, now(),
        -- F11. Both NULL, unconditionally, on every insert path.
        null, null)
    on conflict on constraint membership_pkey do nothing;
  exception
    when unique_violation then
      -- membership_transaction_unique: this subscription is already established
      -- to a DIFFERENT identity. Not a race to retry -- a conflict to record.
      insert into public.membership_binding_conflict as c (
          user_id, environment, original_transaction_id, conflict_kind)
      values (p_user_id, p_environment, p_original_transaction_id,
              'transaction_owned_by_other_identity')
      on conflict (user_id, environment, original_transaction_id) do update
         set observed_count = c.observed_count + 1,
             last_seen_at   = now();

      return jsonb_build_object(
        'outcome', 'conflict',
        'reason', 'subscription already established to another identity',
        'established', false);
  end;

  if found then
    return jsonb_build_object(
      'outcome', 'established',
      'established', true,
      'binding_method', v_method,
      'entitled', v_entitled);
  end if;

  -- A row already existed for this (identity, environment). OWNERSHIP IS
  -- ESTABLISHED ONCE: binding_method and bound_at are not re-provenanced. The
  -- refresh goes through the CANONICAL writer, so ordering, entitlement
  -- derivation and cleanup scheduling remain defined in exactly one place.
  select m.binding_method into v_existing
    from public.membership m
   where m.user_id = p_user_id and m.environment = p_environment;

  return jsonb_build_object(
    'outcome', 'already_established',
    'established', false,
    'binding_method', v_existing,
    'refresh', public.membership_apply_state_v1(
                 p_user_id, p_environment, p_original_transaction_id,
                 p_state, null));
end
$function$

CREATE OR REPLACE FUNCTION public.membership_ingest_notification_v1(p_event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_rec         jsonb;
  v_id          uuid;
  v_token       uuid    := nullif(p_event->>'app_account_token', '')::uuid;
  v_disposition text    := coalesce(p_event->>'disposition', 'unsupported');
  v_user        uuid;
  v_applied     jsonb;
  v_outcome     text;
  v_category    text;
begin
  v_rec := public.membership_record_notification_v1(p_event);
  v_id  := (v_rec->>'id')::uuid;

  -- A replay short-circuits before ANY state work. The counter has already been
  -- incremented, the stored outcome of the first delivery is untouched, and
  -- 'duplicate' is returned rather than stored (B-26).
  if (v_rec->>'duplicate')::boolean then
    return jsonb_build_object(
      'outcome', 'duplicate',
      'notification_id', v_id,
      'delivery_count', (v_rec->>'delivery_count')::integer);
  end if;

  if v_disposition = 'state' then
    v_user := public.membership_resolve_binding_v1(v_token);
    if v_user is null then
      -- THE PRODUCTION CASE UNTIL U5 SHIPS, and it is ordinary traffic rather
      -- than a reject. No appAccountToken exists on any Apple subscription yet,
      -- so every real notification lands here.
      v_outcome := 'ignored'; v_category := 'unmapped';
    else
      v_applied := public.membership_apply_state_v1(
        v_user,
        p_event->>'environment',
        p_event->>'original_transaction_id',
        p_event->'state',
        nullif(p_event->>'notification_uuid', '')::uuid);
      v_outcome := v_applied->>'outcome';        -- 'applied', 'stale' or 'ignored'
      -- MAPPED, COMPLETE, AND STILL NOT WRITABLE. The token resolves to a live
      -- binding and Apple's state is usable, but no authoritative membership row
      -- exists -- so there is nothing to update and U4 will not originate one.
      -- Recorded rather than discarded, because U5 needs to know this arrived.
      if v_outcome = 'ignored' then
        v_category := 'unestablished';
      else
        v_category := null;
      end if;
    end if;
  elsif v_disposition = 'incomplete' then
    -- B-25. Apple-signed and possibly ownership-mapped, but carrying neither an
    -- orderable signedDate nor a usable paid-through date. WRITE NOTHING and ask
    -- for a live read. Crucially this leaves entitlement_ended_at and
    -- pending_cleanup_at untouched: ambiguous state must never schedule cleanup.
    v_outcome := 'ignored'; v_category := 'incomplete';
  elsif v_disposition = 'not_applicable' then
    v_outcome := 'ignored'; v_category := 'not_applicable';
  else
    v_outcome := 'rejected'; v_category := 'unsupported';
  end if;

  update public.membership_notification
     set outcome = v_outcome, failure_category = v_category
   where id = v_id;

  return jsonb_build_object(
    'outcome', v_outcome,
    'failure_category', v_category,
    'notification_id', v_id,
    'mapped', v_user is not null,
    'needs_reconciliation', v_disposition = 'incomplete',
    'needs_establishment', coalesce((v_applied->>'needs_establishment')::boolean, false),
    'applied', v_applied);
end
$function$

CREATE OR REPLACE FUNCTION public.reply_to_commenter(p_post_id uuid, p_recipient_user_id uuid, p_body text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_owner uuid;
  v_ok boolean;
begin
  if not public.enforcement_gate('rpc.reply_to_commenter') then
    raise exception 'not permitted';
  end if;
  if p_body is null or btrim(p_body) = '' then
    return;
  end if;

  select owner_user_id into v_owner
  from public.posts
  where id = p_post_id;

  if v_owner is null then
    raise exception 'post not found';
  end if;

  if auth.uid() <> v_owner then
    raise exception 'owner only';
  end if;

  select exists (
    select 1
    from public.post_comments c
    where c.post_id = p_post_id
      and c.owner_user_id = v_owner
      and c.author_user_id = p_recipient_user_id
      and c.author_user_id <> v_owner
  ) into v_ok;

  if not v_ok then
    raise exception 'invalid recipient';
  end if;

  insert into public.post_comments (post_id, owner_user_id, author_user_id, recipient_user_id, body)
  values (p_post_id, v_owner, v_owner, p_recipient_user_id, p_body);
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_to_commenters(p_post_id uuid, p_body text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_owner uuid;
begin
  if not public.enforcement_gate('rpc.respond_to_commenters') then
    raise exception 'not permitted';
  end if;
  if p_body is null or btrim(p_body) = '' then
    return;
  end if;

  select owner_user_id into v_owner
  from public.posts
  where id = p_post_id;

  if v_owner is null then
    raise exception 'post not found';
  end if;

  if auth.uid() <> v_owner then
    raise exception 'owner only';
  end if;

  insert into public.post_comments (post_id, owner_user_id, author_user_id, recipient_user_id, body)
  select
    p_post_id,
    v_owner,
    v_owner,
    c.author_user_id,
    p_body
  from (
    select distinct c.author_user_id
    from public.post_comments c
    where c.post_id = p_post_id
      and c.owner_user_id = v_owner
      and c.author_user_id <> v_owner
  ) c;
end;
$function$

CREATE OR REPLACE FUNCTION public.tg_membership_propagate_entitled_until()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid; v_until timestamptz;
begin
  if tg_op = 'DELETE' then v_uid := old.user_id; else v_uid := new.user_id; end if;
  v_until := public.membership_entitled_until(v_uid);

  update public.posts             set owner_entitled_until    = v_until
   where owner_user_id    = v_uid and owner_entitled_until    is distinct from v_until;
  update public.post_shares       set owner_entitled_until    = v_until
   where owner_user_id    = v_uid and owner_entitled_until    is distinct from v_until;
  update public.follows           set followed_entitled_until = v_until
   where followed_user_id = v_uid and followed_entitled_until is distinct from v_until;
  update public.account_directory set entitled_until          = v_until
   where user_id          = v_uid and entitled_until          is distinct from v_until;

  return null;
end
$function$

CREATE OR REPLACE FUNCTION public.tg_set_entitled_until()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  case tg_table_name
    when 'posts'             then new.owner_entitled_until    := public.membership_entitled_until(new.owner_user_id);
    when 'post_shares'       then new.owner_entitled_until    := public.membership_entitled_until(new.owner_user_id);
    when 'follows'           then new.followed_entitled_until := public.membership_entitled_until(new.followed_user_id);
    when 'account_directory' then new.entitled_until          := public.membership_entitled_until(new.user_id);
  end case;
  return new;
end
$function$
